<template>
  <section class="page-grid agent-detail-page" v-loading="loading">
    <div class="agent-detail-topbar">
      <el-button text :icon="ArrowLeft" @click="router.push('/agents')">返回智能体目录</el-button>
      <div class="agent-detail-actions"><el-button :icon="Refresh" :loading="loading" @click="load">刷新观测</el-button><el-button type="primary" @click="changeStatus(agent?.lifecycleStatus === 'ACTIVE' ? 'PAUSED' : 'ACTIVE')">{{ agent?.lifecycleStatus === 'ACTIVE' ? '暂停智能体' : '启用智能体' }}</el-button></div>
    </div>

    <el-card v-if="agent" shadow="never" class="panel agent-profile-hero">
      <div class="agent-profile-main">
        <div class="agent-avatar agent-profile-avatar" :class="`agent-avatar-${agent.riskLevel.toLowerCase()}`">{{ initials(agent.name) }}</div>
        <div class="agent-profile-copy"><div class="agent-profile-title"><h2>{{ agent.name }}</h2><el-tag :type="statusType(agent.lifecycleStatus)">{{ statusText(agent.lifecycleStatus) }}</el-tag><el-tag :type="riskType(agent.riskLevel)" effect="plain">{{ riskText(agent.riskLevel) }}风险</el-tag></div><p>{{ agent.description || '尚未填写业务说明' }}</p><div class="agent-profile-meta"><span>{{ agent.code }}</span><i></i><span>{{ agent.ownerDepartment || '未分配部门' }}</span><i></i><span>责任人：{{ agent.ownerUser || '未分配' }}</span><i></i><span>更新于 {{ formatDate(agent.updatedAt) }}</span></div></div>
      </div>
      <div class="agent-profile-health"><span>观测状态</span><strong :class="healthClass">{{ healthLabel }}</strong><small>{{ lastObservedLabel }}</small></div>
    </el-card>

    <el-alert v-if="!agent" type="warning" :closable="false" title="未找到该智能体，请返回目录重新选择。" />

    <div v-if="agent" class="agent-detail-tabs" role="tablist">
      <button v-for="tab in tabs" :key="tab.key" :class="{ active: activeTab === tab.key }" @click="activeTab = tab.key"><el-icon><component :is="tab.icon" /></el-icon>{{ tab.label }}<b v-if="tab.count !== undefined">{{ tab.count }}</b></button>
    </div>

    <template v-if="agent">
      <div v-show="activeTab === 'overview'" class="agent-detail-content">
        <div class="metric-strip agent-detail-metrics"><div class="small-box box-primary"><div><strong>{{ formatNumber(totalTokens) }}</strong><span>总 Token</span></div><el-icon><Tickets /></el-icon></div><div class="small-box box-success"><div><strong>{{ modelEvents.length }}</strong><span>模型调用</span></div><el-icon><Connection /></el-icon></div><div class="small-box box-info"><div><strong>{{ tools.length }}</strong><span>工具调用</span></div><el-icon><Tools /></el-icon></div><div class="small-box box-warning"><div><strong>{{ formatMoney(totalCost) }}</strong><span>累计费用 USD</span></div><el-icon><Money /></el-icon></div></div>
        <div class="agent-detail-grid agent-detail-grid-main"><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>智能体摘要</span><el-tag size="small" effect="plain">实时数据</el-tag></div></template><div class="attribute-grid"><div><span>业务类别</span><strong>{{ agent.category || '未分类' }}</strong></div><div><span>运行实例</span><strong>{{ runtimes.length }} 个</strong></div><div><span>能力标签</span><strong>{{ capabilities.length }} 项</strong></div><div><span>最近 Trace</span><strong class="mono">{{ latestTraceId || '暂无' }}</strong></div><div><span>成功率</span><strong>{{ successRate }}%</strong></div><div><span>平均延迟</span><strong>{{ averageLatency }} ms</strong></div></div></el-card><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>运行健康</span><span class="muted">当前实例状态</span></div></template><div class="runtime-health-list"><div v-for="runtime in runtimes" :key="runtime.id"><span class="runtime-status-dot" :class="runtime.status.toLowerCase()"></span><div><strong>{{ runtime.instanceKey }}</strong><small>{{ runtime.endpoint }} · {{ runtime.protocol }}</small></div><el-tag size="small" :type="runtime.status === 'ONLINE' ? 'success' : runtime.status === 'DEGRADED' ? 'warning' : 'info'">{{ runtimeStatusLabel(runtime.status) }}</el-tag></div><el-empty v-if="!runtimes.length" description="尚未登记运行实例" :image-size="60" /></div></el-card></div>
        <el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>最近活动</span><el-button link type="primary" @click="activeTab = 'trace'">查看完整 Trace</el-button></div></template><el-table :data="recentActivity" size="small"><el-table-column prop="time" label="时间" width="170" /><el-table-column prop="kind" label="类型" width="110" /><el-table-column prop="title" label="活动" min-width="240" /><el-table-column prop="detail" label="详情" min-width="260" show-overflow-tooltip /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag size="small" :type="row.tone">{{ row.status }}</el-tag></template></el-table-column></el-table><el-empty v-if="!recentActivity.length" description="暂无活动记录" :image-size="70" /></el-card>
      </div>

      <div v-show="activeTab === 'runtime'" class="agent-detail-content"><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>运行实例</span><span class="muted">心跳、端点与负载</span></div></template><el-table :data="runtimes"><el-table-column prop="instanceKey" label="实例" min-width="180" /><el-table-column prop="endpoint" label="端点" min-width="250" /><el-table-column prop="protocol" label="协议" width="110" /><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="row.status === 'ONLINE' ? 'success' : row.status === 'DEGRADED' ? 'warning' : 'info'">{{ runtimeStatusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="负载" width="180"><template #default="{ row }"><el-progress :percentage="Math.round(row.loadScore * 100)" :stroke-width="7" :show-text="false" /><small>{{ Math.round(row.loadScore * 100) }}%</small></template></el-table-column><el-table-column label="最后心跳" width="190"><template #default="{ row }">{{ formatDate(row.lastHeartbeatAt) }}</template></el-table-column></el-table><el-empty v-if="!runtimes.length" description="尚未登记运行实例" /></el-card><el-card shadow="never" class="panel"><template #header><span>能力与技能</span></template><div class="capability-list"><el-tag v-for="capability in capabilities" :key="capability.id" effect="plain" size="large">{{ capability.name }}<small>{{ capability.capability }}</small></el-tag><el-empty v-if="!capabilities.length" description="尚未登记能力" :image-size="70" /></div></el-card></div>

      <div v-show="activeTab === 'trace'" class="agent-detail-content"><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>Trace 时间线</span><span class="muted">{{ spans.length }} 个 Span · {{ content.length }} 条内容观测</span></div></template><div class="agent-trace-timeline"><div v-for="(span, index) in spans" :key="span.id" class="agent-trace-row"><div class="agent-trace-index">{{ String(index + 1).padStart(2, '0') }}</div><div class="agent-trace-line"></div><div class="agent-trace-body"><div><strong>{{ span.spanName }}</strong><el-tag size="small" :type="traceTone(span.spanKind)">{{ traceKindLabel(span.spanKind) }}</el-tag><el-tag v-if="span.status" size="small" effect="plain">{{ statusLabel(span.status) }}</el-tag></div><p>{{ span.operation || '未命名操作' }} · {{ span.durationMs }} ms · {{ formatDate(span.observedAt) }}</p><small class="mono">Trace {{ span.traceId }} · Span {{ span.spanId }}</small><div class="trace-attribute-chips"><span v-if="span.toolName">工具：{{ span.toolName }}</span><span v-if="span.mcpServerName">MCP：{{ span.mcpServerName }}</span><span v-if="span.ragSource">知识源：{{ span.ragSource }}</span></div></div></div><el-empty v-if="!spans.length" description="该智能体暂无 Trace。请确认 OTLP 或网关遥测已接入。" /></div></el-card><el-card shadow="never" class="panel"><template #header><span>输入 / 输出观测</span></template><el-table :data="content" size="small"><el-table-column label="方向" width="110"><template #default="{ row }"><el-tag size="small" :type="row.direction === 'INPUT' ? 'warning' : 'success'">{{ directionLabel(row.direction) }}</el-tag></template></el-table-column><el-table-column prop="modelName" label="模型" width="160" /><el-table-column prop="captureMode" label="捕获模式" width="120" /><el-table-column prop="estimatedTokens" label="Token" width="100" /><el-table-column prop="sensitivity" label="敏感级别" width="120" /><el-table-column prop="contentHash" label="内容指纹" min-width="250" show-overflow-tooltip /><el-table-column label="时间" width="170"><template #default="{ row }">{{ formatDate(row.observedAt) }}</template></el-table-column></el-table><el-empty v-if="!content.length" description="暂无内容观测（当前仅展示脱敏元数据）" /></el-card></div>

      <div v-show="activeTab === 'models'" class="agent-detail-content"><div class="agent-detail-grid agent-detail-grid-main"><el-card shadow="never" class="panel"><template #header><span>Token 消耗趋势</span></template><TrendChart :option="tokenTrendOption" height="280px" /></el-card><el-card shadow="never" class="panel"><template #header><span>模型分布</span></template><div class="model-breakdown-list"><div v-for="item in modelBreakdown" :key="item.model"><div><strong>{{ item.model }}</strong><span>{{ item.provider }}</span></div><b>{{ formatNumber(item.tokens) }}<small> Token</small></b></div><el-empty v-if="!modelBreakdown.length" description="暂无模型调用" :image-size="60" /></div></el-card></div><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>大模型调用记录</span><span class="muted">完整元数据，不展示提示词正文</span></div></template><el-table :data="modelEvents" size="small"><el-table-column prop="observedAt" label="时间" width="175"><template #default="{ row }">{{ formatDate(row.observedAt) }}</template></el-table-column><el-table-column prop="provider" label="供应商" width="130" /><el-table-column prop="modelName" label="模型" width="160" /><el-table-column label="Token" width="140"><template #default="{ row }">{{ formatNumber(row.totalTokens) }}（入 {{ row.inputTokens }} / 出 {{ row.outputTokens }}）</template></el-table-column><el-table-column prop="latencyMs" label="延迟" width="100"><template #default="{ row }">{{ row.latencyMs }} ms</template></el-table-column><el-table-column prop="moneyCost" label="费用" width="110"><template #default="{ row }">{{ row.moneyCost.toFixed(4) }} {{ row.currency }}</template></el-table-column><el-table-column label="Trace" min-width="220"><template #default="{ row }"><span class="mono">{{ row.traceId || '—' }}</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag size="small" :type="row.status === 'SUCCEEDED' ? 'success' : row.status === 'FAILED' ? 'danger' : 'warning'">{{ modelStatusLabel(row.status) }}</el-tag></template></el-table-column></el-table><el-empty v-if="!modelEvents.length" description="暂无模型调用记录" /></el-card></div>

      <div v-show="activeTab === 'tools'" class="agent-detail-content"><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>工具与 MCP 调用</span><span class="muted">{{ tools.length }} 条观测</span></div></template><el-table :data="tools"><el-table-column prop="observedAt" label="时间" width="175"><template #default="{ row }">{{ formatDate(row.observedAt) }}</template></el-table-column><el-table-column prop="toolName" label="工具名称" min-width="180" /><el-table-column prop="toolKind" label="类型" width="110"><template #default="{ row }">{{ row.toolKind === 'MCP' ? 'MCP 服务' : '工具' }}</template></el-table-column><el-table-column prop="mcpServerName" label="MCP 服务" min-width="150" /><el-table-column prop="durationMs" label="耗时" width="100"><template #default="{ row }">{{ row.durationMs }} ms</template></el-table-column><el-table-column label="Trace" min-width="220"><template #default="{ row }"><span class="mono">{{ row.traceId || '—' }}</span></template></el-table-column><el-table-column label="状态" width="105"><template #default="{ row }"><el-tag size="small" :type="row.status === 'SUCCEEDED' ? 'success' : row.status === 'FAILED' ? 'danger' : 'warning'">{{ toolStatusLabel(row.status) }}</el-tag></template></el-table-column></el-table><el-empty v-if="!tools.length" description="暂无工具调用记录" /></el-card><div class="agent-detail-grid"><el-card shadow="never" class="panel"><template #header><span>知识使用</span></template><div class="attribute-grid"><div><span>交互次数</span><strong>{{ knowledge.length }}</strong></div><div><span>已采用</span><strong>{{ knowledge.filter(item => item.adopted).length }}</strong></div><div><span>已复用</span><strong>{{ knowledge.filter(item => item.reused).length }}</strong></div><div><span>平均质量</span><strong>{{ knowledgeQuality }}</strong></div></div></el-card><el-card shadow="never" class="panel"><template #header><span>知识最近记录</span></template><div class="compact-record-list"><div v-for="item in knowledge.slice(0, 5)" :key="item.id"><strong>{{ item.inputSummary || item.interactionKey }}</strong><span>{{ statusLabel(item.status) }} · {{ formatDate(item.createdAt) }}</span></div><el-empty v-if="!knowledge.length" description="暂无知识交互" :image-size="60" /></div></el-card></div></div>

      <div v-show="activeTab === 'governance'" class="agent-detail-content"><el-card shadow="never" class="panel"><template #header><div class="panel-header"><span>治理与数据访问</span><span class="muted">内部信息、保密信息与策略动作</span></div></template><div class="governance-agent-summary"><div><span>治理事件</span><strong>{{ governance.length }}</strong></div><div><span>内部信息</span><strong class="is-warning">{{ governance.filter(item => item.internalData).length }}</strong></div><div><span>公司保密信息</span><strong class="is-danger">{{ governance.filter(item => item.companySecret).length }}</strong></div><div><span>阻断 / 脱敏</span><strong>{{ governance.filter(item => ['BLOCK', 'REDACT'].includes(item.action)).length }}</strong></div></div><el-table :data="governance"><el-table-column prop="observedAt" label="时间" width="175"><template #default="{ row }">{{ formatDate(row.observedAt) }}</template></el-table-column><el-table-column label="方向" width="145"><template #default="{ row }">{{ directionGovernanceLabel(row.direction) }}</template></el-table-column><el-table-column prop="dataCategory" label="数据类别" min-width="180" /><el-table-column prop="sensitivity" label="敏感级别" width="125" /><el-table-column prop="action" label="策略动作" width="130"><template #default="{ row }"><el-tag size="small" :type="row.action === 'BLOCK' ? 'danger' : row.action === 'REDACT' ? 'warning' : 'success'">{{ actionLabel(row.action) }}</el-tag></template></el-table-column><el-table-column label="Trace" min-width="220"><template #default="{ row }"><span class="mono">{{ row.traceId || '—' }}</span></template></el-table-column></el-table><el-empty v-if="!governance.length" description="暂无治理事件" /></el-card></div>

      <div v-show="activeTab === 'identity'" class="agent-detail-content"><el-card shadow="never" class="panel"><template #header><span>身份与管理属性</span></template><div class="agent-identity-grid"><div><span>智能体 ID</span><strong class="mono">{{ agent.id }}</strong></div><div><span>唯一编码</span><strong class="mono">{{ agent.code }}</strong></div><div><span>责任部门</span><strong>{{ agent.ownerDepartment || '未分配' }}</strong></div><div><span>责任人</span><strong>{{ agent.ownerUser || '未分配' }}</strong></div><div><span>业务类别</span><strong>{{ agent.category || '未分类' }}</strong></div><div><span>创建时间</span><strong>{{ formatDate(agent.createdAt) }}</strong></div><div><span>更新时间</span><strong>{{ formatDate(agent.updatedAt) }}</strong></div><div><span>风险等级</span><strong>{{ riskText(agent.riskLevel) }}</strong></div></div></el-card><el-card shadow="never" class="panel"><template #header><span>关联任务</span></template><el-table :data="tasks"><el-table-column prop="taskType" label="任务类型" min-width="180" /><el-table-column prop="inputSummary" label="输入摘要" min-width="260" show-overflow-tooltip /><el-table-column prop="status" label="状态" width="110" /><el-table-column prop="tokenCost" label="Token" width="100" /><el-table-column prop="createdAt" label="创建时间" width="175"><template #default="{ row }">{{ formatDate(row.createdAt) }}</template></el-table-column></el-table><el-empty v-if="!tasks.length" description="暂无关联任务" /></el-card></div>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ArrowRight, Collection, Connection, DataAnalysis, Document, Lock, Money, Refresh, Tickets, Tools } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import type { EChartsOption } from 'echarts'
import TrendChart from '@/components/TrendChart.vue'
import { EapApi } from '@/api/eap'
import type { Agent, AgentCapability, AgentRuntimeInstance, AgentTask, ContentDirection, ContentObservation, GovernanceDataAction, GovernanceDataEvent, KnowledgeInteraction, ModelInvocationEvent, ModelInvocationStatus, RiskLevel, RuntimeStatus, ToolInvocationEvent, TraceSpanKind, TraceSpanObservation } from '@/types/domain'

const route = useRoute(); const router = useRouter()
const loading = ref(false); const agent = ref<Agent>(); const activeTab = ref('overview')
const capabilities = ref<AgentCapability[]>([]); const runtimes = ref<AgentRuntimeInstance[]>([]); const modelEvents = ref<ModelInvocationEvent[]>([]); const spans = ref<TraceSpanObservation[]>([]); const tools = ref<ToolInvocationEvent[]>([]); const content = ref<ContentObservation[]>([]); const knowledge = ref<KnowledgeInteraction[]>([]); const governance = ref<GovernanceDataEvent[]>([]); const tasks = ref<AgentTask[]>([])
const agentId = computed(() => Number(route.params.id))
const tabs = computed(() => [{ key: 'overview', label: '总览', icon: DataAnalysis }, { key: 'runtime', label: '运行与能力', icon: Connection, count: runtimes.value.length }, { key: 'trace', label: 'Trace 观测', icon: Document, count: spans.value.length }, { key: 'models', label: '模型与 Token', icon: Tickets, count: modelEvents.value.length }, { key: 'tools', label: '工具与知识', icon: Tools, count: tools.value.length }, { key: 'governance', label: '治理风险', icon: Lock, count: governance.value.length }, { key: 'identity', label: '身份属性', icon: Collection }])
const totalTokens = computed(() => modelEvents.value.reduce((sum, item) => sum + (item.totalTokens || 0), 0)); const totalCost = computed(() => modelEvents.value.reduce((sum, item) => sum + (item.moneyCost || 0), 0)); const successRate = computed(() => modelEvents.value.length ? Math.round(modelEvents.value.filter(item => item.status === 'SUCCEEDED').length / modelEvents.value.length * 100) : 0); const averageLatency = computed(() => modelEvents.value.length ? Math.round(modelEvents.value.reduce((sum, item) => sum + item.latencyMs, 0) / modelEvents.value.length) : 0); const latestTraceId = computed(() => modelEvents.value.find(item => item.traceId)?.traceId || spans.value[0]?.traceId || ''); const healthLabel = computed(() => runtimes.value.some(item => item.status === 'ONLINE') ? '健康' : runtimes.value.some(item => item.status === 'DEGRADED') ? '降级' : runtimes.value.length ? '离线' : '未接入'); const healthClass = computed(() => healthLabel.value === '健康' ? 'is-success' : healthLabel.value === '降级' ? 'is-warning' : 'is-danger'); const lastObservedLabel = computed(() => modelEvents.value[0] ? `最近观测 ${formatDate(modelEvents.value[0].observedAt)}` : '暂无模型调用观测')
const knowledgeQuality = computed(() => knowledge.value.length ? `${Math.round(knowledge.value.reduce((sum, item) => sum + (item.qualityScore || 0), 0) / knowledge.value.length * 100)}%` : '—')
const modelBreakdown = computed(() => { const map = new Map<string, { model: string; provider: string; tokens: number }>(); modelEvents.value.forEach(item => { const key = `${item.provider}/${item.modelName}`; const current = map.get(key) || { model: item.modelName, provider: item.provider, tokens: 0 }; current.tokens += item.totalTokens || 0; map.set(key, current) }); return [...map.values()].sort((a, b) => b.tokens - a.tokens).slice(0, 8) })
const tokenTrendOption = computed<EChartsOption>(() => { const rows = [...modelEvents.value].slice(0, 14).reverse(); return { tooltip: { trigger: 'axis' }, grid: { left: 42, right: 16, top: 18, bottom: 28 }, xAxis: { type: 'category', data: rows.map(item => formatTime(item.observedAt)), axisLabel: { color: '#7b8ba3' } }, yAxis: { type: 'value', axisLabel: { color: '#7b8ba3' }, splitLine: { lineStyle: { color: '#e8eef6' } } }, series: [{ type: 'bar', barMaxWidth: 22, data: rows.map(item => item.totalTokens || 0), itemStyle: { color: '#3267e8', borderRadius: [4, 4, 0, 0] } }] } })
const recentActivity = computed(() => [...modelEvents.value.slice(0, 6).map(item => ({ time: formatDate(item.observedAt), kind: '模型调用', title: `${item.provider} · ${item.modelName}`, detail: `${formatNumber(item.totalTokens)} Token · ${item.latencyMs} ms`, status: modelStatusLabel(item.status), tone: item.status === 'SUCCEEDED' ? 'success' : 'danger' })), ...tools.value.slice(0, 4).map(item => ({ time: formatDate(item.observedAt), kind: item.toolKind === 'MCP' ? 'MCP' : '工具', title: item.toolName, detail: `${item.durationMs} ms · ${item.traceId || '无 Trace'}`, status: toolStatusLabel(item.status), tone: item.status === 'SUCCEEDED' ? 'success' : 'warning' }))].slice(0, 8))

async function load() { loading.value = true; try { const [agents, nextCapabilities, nextRuntimes, nextModels, nextSpans, nextTools, nextContent, nextKnowledge, nextGovernance, nextTasks] = await Promise.all([EapApi.listAgents(), EapApi.listAgentCapabilities(agentId.value), EapApi.listAgentRuntimeInstances(agentId.value), EapApi.listModelInvocationEvents({ agentId: agentId.value, limit: 500 }), EapApi.listTraceSpanObservations({ agentId: agentId.value, limit: 500 }), EapApi.listToolInvocationEvents({ agentId: agentId.value, limit: 500 }), EapApi.listContentObservations({ agentId: agentId.value, limit: 500 }), EapApi.listKnowledgeInteractions(500), EapApi.listGovernanceDataEvents(500), EapApi.listTasks()]); agent.value = agents.find(item => item.id === agentId.value); capabilities.value = nextCapabilities; runtimes.value = nextRuntimes; modelEvents.value = nextModels; spans.value = nextSpans; tools.value = nextTools; content.value = nextContent; knowledge.value = nextKnowledge.filter(item => item.agentId === agentId.value); governance.value = nextGovernance.filter(item => item.agentId === agentId.value); tasks.value = nextTasks.filter(item => item.agentId === agentId.value) } finally { loading.value = false } }
async function changeStatus(status: 'ACTIVE' | 'PAUSED') { if (!agent.value) return; await EapApi.updateAgentStatus(agent.value.id, status); ElMessage.success(status === 'ACTIVE' ? '智能体已启用' : '智能体已暂停'); await load() }
function initials(name: string) { return Array.from(name || 'A').slice(0, 2).join('').toUpperCase() }; function formatNumber(value: number) { return new Intl.NumberFormat('zh-CN').format(value || 0) }; function formatMoney(value: number) { return `$${(value || 0).toFixed(4)}` }; function formatDate(value?: string) { return value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '—' }; function formatTime(value?: string) { return value ? new Date(value).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) : '—' }
function statusText(status: string) { return ({ DRAFT: '草稿', REVIEWING: '审核中', ACTIVE: '运行中', PAUSED: '已暂停', RETIRED: '已下线', SUCCEEDED: '成功', FAILED: '失败', STARTED: '进行中', CANCELLED: '已取消', RUNNING: '运行中', REQUESTED: '已请求', UNKNOWN: '未知' } as Record<string, string>)[status] || status }; function modelStatusLabel(status: ModelInvocationStatus) { return statusText(status) }; function toolStatusLabel(status: string) { return statusText(status) }; function runtimeStatusLabel(status: RuntimeStatus) { return ({ ONLINE: '在线', DEGRADED: '降级', OFFLINE: '离线' } as Record<string, string>)[status] || status }; function riskText(risk: RiskLevel) { return ({ LOW: '低', MEDIUM: '中', HIGH: '高', CRITICAL: '关键' } as Record<string, string>)[risk] }; function riskType(risk: RiskLevel) { return risk === 'LOW' ? 'success' : risk === 'MEDIUM' ? 'warning' : 'danger' }; function statusType(status: string) { return status === 'ACTIVE' || status === 'SUCCEEDED' || status === 'ONLINE' ? 'success' : status === 'PAUSED' || status === 'DEGRADED' || status === 'STARTED' ? 'warning' : status === 'FAILED' || status === 'CRITICAL' ? 'danger' : 'info' }; function traceKindLabel(kind: TraceSpanKind) { return ({ MODEL: '模型', TOOL: '工具', MCP: 'MCP', RAG: '知识检索', A2A: '智能体协作', AGENT: '智能体' } as Record<string, string>)[kind] || kind }; function traceTone(kind: TraceSpanKind) { return kind === 'MODEL' ? 'primary' : kind === 'TOOL' || kind === 'MCP' ? 'warning' : kind === 'RAG' ? 'success' : 'info' }; function statusLabel(status: string) { return statusText(status) }; function directionLabel(direction: ContentDirection) { return ({ INPUT: '模型输入', OUTPUT: '模型输出', TOOL_INPUT: '工具输入', TOOL_OUTPUT: '工具输出', SYSTEM: '系统信息' } as Record<string, string>)[direction] || direction }; function directionGovernanceLabel(direction: string) { return ({ INPUT_TO_MODEL: '进入大模型', OUTPUT_FROM_MODEL: '模型输出', TOOL_INPUT: '工具输入', TOOL_OUTPUT: '工具输出' } as Record<string, string>)[direction] || direction }; function actionLabel(action: GovernanceDataAction) { return ({ ALLOW: '允许', WARN: '告警', REDACT: '脱敏', BLOCK: '阻断', APPROVAL_REQUIRED: '需审批' } as Record<string, string>)[action] || action }
onMounted(load)
</script>
